CREATE TABLE IF NOT EXISTS bak_20261026_rem_a6_issue_desc AS
SELECT id, description FROM agent_issues WHERE id IN (2805, 100168, 2582, 2596, 2754, 1000152, 1000156, 1000161, 1000162, 1000315);

UPDATE agent_issues SET updated_at = CAST(strftime('%s', 'now') AS INTEGER) * 1000, description = description || char(10) || char(10) ||
 'REM-A6 2026-10-26 (infrastructure remediation session rem-a6): no fleet or cloud path exists for the remaining piece, so this stays with the owner card 125. Checked on the owner machine: the sync script exists as DeepChatData/dotdeepchat/scripts/sync_system_prompt.py (version 4.0, 140 lines), byte-identical to scripts/sync_system_prompt.py of the public repository QNFO/qnfo-ops, and an older 126-line copy sits in DeepChatData/repo (QNFO/deepchat, private); none of the three contains a work-lock, claim or acquire call. The closing probe reads a work_claims row on prompt-stores/sync_system_prompt.py: a session that takes that claim only to edit the file would make the probe pass without the script taking one, so none did. The change to make (owner machine): acquire the claim before the write and release after, refuse a store newer than the canonical file unless --force, write the default row too.'
WHERE id = 2805 AND instr(description, 'REM-A6 2026-10-26') = 0;

UPDATE agent_issues SET updated_at = CAST(strftime('%s', 'now') AS INTEGER) * 1000, description = description || char(10) || char(10) ||
 'REM-A6 2026-10-26: step 1 of the order of work is already shipped (github-settings-actions report: main_push_identities, main_push_paths, pushers_last_100, workflow_problems). Live today: 16 workflows run git push; the last 100 updates of main are 46 qnfo-fleet[bot] pr_merge, 36 github-actions[bot] push, 13 rwnq8 pr_merge, 5 qnfo-fleet[bot] push; /rules/branches/main lists deletion and non_fast_forward only. No permission refusal exists for steps 2 to 4 (the 422 of 2026-10-19 was GitHub validating the bypass actor), so nothing here is owner-only yet; what is open is a design choice with fleet-wide blast radius, not taken in this session: (a) put the 41 direct pushes on a bypass-listed identity, which puts the admin token or the App token in 16 workflows, or (b) move the status-artifact commits (ci-status, fleet-autoaudit artifacts, mirror-sync) off main onto a branch of their own so that the ruleset needs no bypass for them and no token reaches further than it does now. The owner directives of 2026-10-26 (every pull request merged within 10 minutes; the deploy gate is no longer a required check) change the definition of done: the required checks would be guard, mirror-guard and comparator, and the fleet App must still merge. Next: take choice (a) or (b), then step 2 as one workflow-only pull request.'
WHERE id = 100168 AND instr(description, 'REM-A6 2026-10-26') = 0;

UPDATE agent_issues SET updated_at = CAST(strftime('%s', 'now') AS INTEGER) * 1000, description = description || char(10) || char(10) ||
