UPDATE remediation_contracts SET ts = datetime('now'), status = 'active', verify_transport = 'code-read',
  verify_probe = '{"paths": ["qnfo-ops/worker.js"], "contains": "WORKSPACE-STAGE-1"}',
  last_verdict = NULL, attempts = 0, deferred_since = NULL, next_due_at = datetime('now'), module = 'infra-probes-1',
  precondition = 'INFRA-NOTES-1: issue 1000177 defect (workspace_write and the container shell tools use two filesystems that share nothing) is a code defect of qnfo-ops',
  action = 'MEASURES the defect: qnfo-ops/worker.js on main carries WORKSPACE-STAGE-1, the staging of ops-workspace files into the container before shell_exec and container_workspace_exec run (stage argument, named /workspace/<path>, the answer lists the staged files and the root). workspace-stage.test.mjs runs the generated prelude in a real bash: write probe.sh, run it, compare the bytes.'
WHERE class = 'issue-1000177';

